// ------------------------------------------------------------------
//  Design Unit:    load_kv_fill_0_core_core_fsm
//  FSM Module
// ------------------------------------------------------------------


module load_kv_fill_0_core_core_fsm (
  clk, rst, core_wen, fsm_output, l_S_jjf_0_jjf_C_0_tr0, l_S_tile_f_0_tile_f_C_0_tr0
);
  input clk;
  input rst;
  input core_wen;
  output [3:0] fsm_output;
  reg [3:0] fsm_output;
  input l_S_jjf_0_jjf_C_0_tr0;
  input l_S_tile_f_0_tile_f_C_0_tr0;


  // FSM State Type Declaration for load_kv_fill_0_core_core_fsm_1
  parameter
    main_C_0 = 2'd0,
    l_S_jjf_0_jjf_C_0 = 2'd1,
    l_S_tile_f_0_tile_f_C_0 = 2'd2,
    main_C_1 = 2'd3;

  reg [1:0] state_var;
  reg [1:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : load_kv_fill_0_core_core_fsm_1
    case (state_var)
      l_S_jjf_0_jjf_C_0 : begin
        fsm_output = 4'b0010;
        if ( l_S_jjf_0_jjf_C_0_tr0 ) begin
          state_var_NS = l_S_tile_f_0_tile_f_C_0;
        end
        else begin
          state_var_NS = l_S_jjf_0_jjf_C_0;
        end
      end
      l_S_tile_f_0_tile_f_C_0 : begin
        fsm_output = 4'b0100;
        if ( l_S_tile_f_0_tile_f_C_0_tr0 ) begin
          state_var_NS = main_C_1;
        end
        else begin
          state_var_NS = l_S_jjf_0_jjf_C_0;
        end
      end
      main_C_1 : begin
        fsm_output = 4'b1000;
        state_var_NS = main_C_0;
      end
      // main_C_0
      default : begin
        fsm_output = 4'b0001;
        state_var_NS = l_S_jjf_0_jjf_C_0;
      end
    endcase
  end

  always @(posedge clk) begin
    if ( rst ) begin
      state_var <= main_C_0;
    end
    else if ( core_wen ) begin
      state_var <= state_var_NS;
    end
  end

endmodule

