module pe_1_1_blk_run_core_core_fsm (
  clk, rst, core_wen, fsm_output, for_for_C_0_tr0, for_C_0_tr0, l_S_dq0i_0_dq0i_C_0_tr0,
      l_S_bm_1_bm_C_0_tr0, l_S_qt_1_qt33_C_0_tr0
);
  input clk;
  input rst;
  input core_wen;
  output [5:0] fsm_output;
  reg [5:0] fsm_output;
  input for_for_C_0_tr0;
  input for_C_0_tr0;
  input l_S_dq0i_0_dq0i_C_0_tr0;
  input l_S_bm_1_bm_C_0_tr0;
  input l_S_qt_1_qt33_C_0_tr0;


  // FSM State Type Declaration for pe_1_1_blk_run_core_core_fsm_1
  parameter
    main_C_0 = 3'd0,
    for_for_C_0 = 3'd1,
    for_C_0 = 3'd2,
    l_S_dq0i_0_dq0i_C_0 = 3'd3,
    l_S_bm_1_bm_C_0 = 3'd4,
    l_S_qt_1_qt33_C_0 = 3'd5;

  reg [2:0] state_var;
  reg [2:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : pe_1_1_blk_run_core_core_fsm_1
    case (state_var)
      for_for_C_0 : begin
        fsm_output = 6'b000010;
        if ( for_for_C_0_tr0 ) begin
          state_var_NS = for_C_0;
        end
        else begin
          state_var_NS = for_for_C_0;
        end
      end
      for_C_0 : begin
        fsm_output = 6'b000100;
        if ( for_C_0_tr0 ) begin
          state_var_NS = l_S_dq0i_0_dq0i_C_0;
        end
        else begin
          state_var_NS = for_for_C_0;
        end
      end
      l_S_dq0i_0_dq0i_C_0 : begin
        fsm_output = 6'b001000;
        if ( l_S_dq0i_0_dq0i_C_0_tr0 ) begin
          state_var_NS = l_S_bm_1_bm_C_0;
        end
        else begin
          state_var_NS = l_S_dq0i_0_dq0i_C_0;
        end
      end
      l_S_bm_1_bm_C_0 : begin
        fsm_output = 6'b010000;
        if ( l_S_bm_1_bm_C_0_tr0 ) begin
          state_var_NS = l_S_qt_1_qt33_C_0;
        end
        else begin
          state_var_NS = l_S_bm_1_bm_C_0;
        end
      end
      l_S_qt_1_qt33_C_0 : begin
        fsm_output = 6'b100000;
        if ( l_S_qt_1_qt33_C_0_tr0 ) begin
          state_var_NS = main_C_0;
        end
        else begin
          state_var_NS = l_S_bm_1_bm_C_0;
        end
      end
      // main_C_0
      default : begin
        fsm_output = 6'b000001;
        state_var_NS = for_for_C_0;
      end
    endcase
  end

  always @(posedge clk) begin
    if ( rst ) begin
      state_var <= main_C_0;
    end
    else if ( core_wen ) begin
      state_var <= state_var_NS;
    end
  end

endmodule

