  input l_S_qt_1_qt65_C_0_tr0;


  // FSM State Type Declaration for pe_1_33_blk_run_core_core_fsm_1
  parameter
    main_C_0 = 2'd0,
    l_S_dq2_0_dq2_C_0 = 2'd1,
    l_S_bt_1_bt_C_0 = 2'd2,
    l_S_qt_1_qt65_C_0 = 2'd3;

  reg [1:0] state_var;
  reg [1:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : pe_1_33_blk_run_core_core_fsm_1
    case (state_var)
      l_S_dq2_0_dq2_C_0 : begin
        fsm_output = 4'b0010;
        if ( l_S_dq2_0_dq2_C_0_tr0 ) begin
          state_var_NS = l_S_bt_1_bt_C_0;
        end
        else begin
          state_var_NS = l_S_dq2_0_dq2_C_0;
        end
      end
      l_S_bt_1_bt_C_0 : begin
        fsm_output = 4'b0100;
        if ( l_S_bt_1_bt_C_0_tr0 ) begin
          state_var_NS = l_S_qt_1_qt65_C_0;
        end
        else begin
          state_var_NS = l_S_bt_1_bt_C_0;
        end
      end
      l_S_qt_1_qt65_C_0 : begin
        fsm_output = 4'b1000;
        if ( l_S_qt_1_qt65_C_0_tr0 ) begin
          state_var_NS = main_C_0;
        end
        else begin
          state_var_NS = l_S_bt_1_bt_C_0;
        end
      end
      // main_C_0
      default : begin
        fsm_output = 4'b0001;
        state_var_NS = l_S_dq2_0_dq2_C_0;
      end
    endcase
  end

  always @(posedge clk) begin
    if ( rst ) begin
      state_var <= main_C_0;
    end
    else if ( core_wen ) begin
      state_var <= state_var_NS;
    end
  end

endmodule

