// ------------------------------------------------------------------
//  Design Unit:    store_0_core_core_fsm
//  FSM Module
// ------------------------------------------------------------------


module store_0_core_core_fsm (
  clk, rst, core_wen, fsm_output, l_S_jj2_0_jj2_C_0_tr0, l_S_rs_0_rs_C_0_tr0, l_S_tr_0_tr9_C_0_tr0
);
  input clk;
  input rst;
  input core_wen;
  output [4:0] fsm_output;
  reg [4:0] fsm_output;
  input l_S_jj2_0_jj2_C_0_tr0;
  input l_S_rs_0_rs_C_0_tr0;
  input l_S_tr_0_tr9_C_0_tr0;


  // FSM State Type Declaration for store_0_core_core_fsm_1
  parameter
    main_C_0 = 3'd0,
    l_S_jj2_0_jj2_C_0 = 3'd1,
    l_S_rs_0_rs_C_0 = 3'd2,
    l_S_tr_0_tr9_C_0 = 3'd3,
    main_C_1 = 3'd4;

  reg [2:0] state_var;
  reg [2:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : store_0_core_core_fsm_1
    case (state_var)
      l_S_jj2_0_jj2_C_0 : begin
        fsm_output = 5'b00010;
        if ( l_S_jj2_0_jj2_C_0_tr0 ) begin
          state_var_NS = l_S_rs_0_rs_C_0;
        end
        else begin
          state_var_NS = l_S_jj2_0_jj2_C_0;
        end
      end
      l_S_rs_0_rs_C_0 : begin
        fsm_output = 5'b00100;
        if ( l_S_rs_0_rs_C_0_tr0 ) begin
          state_var_NS = l_S_tr_0_tr9_C_0;
        end
        else begin
          state_var_NS = l_S_jj2_0_jj2_C_0;
        end
      end
      l_S_tr_0_tr9_C_0 : begin
        fsm_output = 5'b01000;
        if ( l_S_tr_0_tr9_C_0_tr0 ) begin
          state_var_NS = main_C_1;
        end
        else begin
          state_var_NS = l_S_jj2_0_jj2_C_0;
        end
      end
      main_C_1 : begin
        fsm_output = 5'b10000;
        state_var_NS = main_C_0;
      end
      // main_C_0
      default : begin
        fsm_output = 5'b00001;
        state_var_NS = l_S_jj2_0_jj2_C_0;
      end
    endcase
  end

  always @(posedge clk) begin
    if ( rst ) begin
      state_var <= main_C_0;
    end
    else if ( core_wen ) begin
      state_var <= state_var_NS;
    end
  end

endmodule

